/*
 * terrain.js -- real elevation, slope, grids and coordinates for the map.
 *
 * Reads window.MARS_DATASET (data/jezero/jezero-data.js, generated by
 * tools/build_jezero_data.py from NASA/USGS products). Nothing here invents
 * values: grids are decoded and interpolated between their nodes, and every
 * position converts to real latitude/longitude on Mars.
 *
 * Map position (nx, ny): nx 0 = west edge, 1 = east edge; ny 0 = north edge,
 * 1 = south edge. The grid nodes are evenly spaced in longitude and latitude
 * (the window is small enough that this is distance-true to about 0.2%).
 *
 * Exposes window.MarsTerrain. The UI should go through window.MarsData
 * (data-layers.js) rather than calling this directly.
 */
(function () {
  "use strict";

  var ds = window.MARS_DATASET;
  if (!ds || !ds.grid || !ds.fields) {
    window.MarsTerrain = {
      ok: false,
      error: "The map data file (data/jezero/jezero-data.js) did not load."
    };
    return;
  }

  var GW = ds.grid.w;
  var GH = ds.grid.h;
  var B = ds.bounds;

  // ---- decoding -------------------------------------------------------------

  function bytesOf(b64) {
    var bin = atob(b64);
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  }

  // Decoded grids, created on first use. uint8 fields keep their raw 0-255
  // values unless the field has a scale; int16 fields are always scaled.
  var cache = {};
  function grid(name) {
    if (cache[name]) return cache[name];
    var f = ds.fields[name];
    if (!f) return null;
    var bytes = bytesOf(f.b64);
    var n = GW * GH;
    var out = new Float32Array(n);
    var i;
    if (f.type === "int16") {
      var view = new DataView(bytes.buffer);
      for (i = 0; i < n; i++) out[i] = view.getInt16(i * 2, true) * f.scale;
    } else {
      var s = f.scale || 1;
      for (i = 0; i < n; i++) out[i] = bytes[i] * s;
    }
    cache[name] = out;
    return out;
  }

  // ---- sampling ---------------------------------------------------------------

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  // Bilinear value of a grid at a map position.
  function bilinear(values, nx, ny) {
    var gx = clamp01(nx) * (GW - 1);
    var gy = clamp01(ny) * (GH - 1);
    var x0 = Math.min(Math.floor(gx), GW - 2);
    var y0 = Math.min(Math.floor(gy), GH - 2);
    var fx = gx - x0;
    var fy = gy - y0;
    var i = y0 * GW + x0;
    var a = values[i], b = values[i + 1], c = values[i + GW], d = values[i + GW + 1];
    return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
  }

  // Value of the nearest node (for categories and no-data-aware fields).
  function nearest(values, nx, ny) {
    var x = Math.round(clamp01(nx) * (GW - 1));
    var y = Math.round(clamp01(ny) * (GH - 1));
    return values[y * GW + x];
  }

  function sampleField(name, nx, ny) {
    var g = grid(name);
    return g ? bilinear(g, nx, ny) : NaN;
  }

  function sampleNearest(name, nx, ny) {
    var g = grid(name);
    return g ? nearest(g, nx, ny) : NaN;
  }

  // Elevation on a w x h lattice covering the whole window (row-major,
  // north row first), the shape MarsData.getElevationGrid() promises.
  function elevationGrid(w, h) {
    var g = grid("elevation");
    var out = new Float32Array(w * h);
    for (var y = 0; y < h; y++) {
      var ny = h > 1 ? y / (h - 1) : 0;
      for (var x = 0; x < w; x++) {
        out[y * w + x] = bilinear(g, w > 1 ? x / (w - 1) : 0, ny);
      }
    }
    return out;
  }

  // ---- coordinates ------------------------------------------------------------

  function toLatLon(nx, ny) {
    return {
      lat: B.north - clamp01(ny) * (B.north - B.south),
      lon: B.west + clamp01(nx) * (B.east - B.west)
    };
  }

  // Unclamped, so callers can tell when a point is outside the window.
  function fromLatLon(lat, lon) {
    return {
      nx: (lon - B.west) / (B.east - B.west),
      ny: (B.north - lat) / (B.north - B.south)
    };
  }

  function inside(p) {
    return p.nx >= 0 && p.nx <= 1 && p.ny >= 0 && p.ny <= 1;
  }

  // Ground distance between two map positions, in km.
  function distanceKm(a, b) {
    var dx = (a.nx - b.nx) * ds.widthKm;
    var dy = (a.ny - b.ny) * ds.heightKm;
    return Math.sqrt(dx * dx + dy * dy);
  }

  window.MarsTerrain = {
    ok: true,
    dataset: ds,
    bounds: { west: B.west, east: B.east, south: B.south, north: B.north },
    widthKm: ds.widthKm,
    heightKm: ds.heightKm,
    grid: function (name) { return grid(name); },
    gridSize: { w: GW, h: GH },
    sampleField: sampleField,
    sampleNearest: sampleNearest,
    // For derived grids (same size as the dataset grid).
    interpolate: bilinear,
    nearestOf: nearest,
    elevationGrid: elevationGrid,
    toLatLon: toLatLon,
    fromLatLon: fromLatLon,
    inside: inside,
    distanceKm: distanceKm
  };
})();
